<?php
require_once __DIR__ . '/../../includes/auth.php';
require_once __DIR__ . '/../../includes/csrf.php';
require_once __DIR__ . '/../../config/database.php';
$admin = require_permission('marks.edit');
if (!in_array($admin['role_name'] ?? '', ['admin','dept_admin','super_admin'], true)) { http_response_code(403); exit('403 Forbidden'); }
$entryId=(int)($_GET['entry_id']??0); $batchId=(int)($_GET['batch_id']??0); $studentId=(int)($_GET['student_id']??0);
$batches=$pdo->query('SELECT batch_id,batch_name,batch_number FROM batches ORDER BY batch_id DESC')->fetchAll(PDO::FETCH_ASSOC); $students=[];
if($batchId){$s=$pdo->prepare('SELECT student_id,roll_no,student_name,designation,qualification,rmc FROM students WHERE batch_id=:b AND (is_deleted=0 OR is_deleted IS NULL) ORDER BY roll_no,student_name');$s->execute([':b'=>$batchId]);$students=$s->fetchAll(PDO::FETCH_ASSOC);}
if($entryId){$s=$pdo->prepare('SELECT batch_id,student_id FROM faculty_marks_entry f JOIN students s ON s.student_id=f.student_id WHERE f.entry_id=:e');$s->execute([':e'=>$entryId]);if($x=$s->fetch()){$batchId=(int)$x['batch_id'];$studentId=(int)$x['student_id'];}}
$student=null;$rows=[];$edit=null;
if($studentId&&$batchId){$s=$pdo->prepare('SELECT * FROM students WHERE student_id=:s AND batch_id=:b AND (is_deleted=0 OR is_deleted IS NULL)');$s->execute([':s'=>$studentId,':b'=>$batchId]);$student=$s->fetch(PDO::FETCH_ASSOC);if($student){$q=$pdo->prepare("SELECT f.entry_id,f.marks_obtained,f.is_absent,p.paper_name,sub.subject_name,at.assessment_type_name,COALESCE(NULLIF(CASE WHEN LOWER(at.assessment_type_name) LIKE '%internal%' THEN psm.subject_max_internal WHEN LOWER(at.assessment_type_name) LIKE '%mid%' THEN psm.subject_max_midterm WHEN LOWER(at.assessment_type_name) LIKE '%final%' THEN psm.subject_max_final END,0),CASE WHEN LOWER(at.assessment_type_name) LIKE '%internal%' THEN p.max_internal WHEN LOWER(at.assessment_type_name) LIKE '%mid%' THEN p.max_midterm WHEN LOWER(at.assessment_type_name) LIKE '%final%' THEN p.max_final END,sfm.max_marks) max_marks FROM faculty_marks_entry f JOIN papers p ON p.paper_id=f.paper_id JOIN subjects sub ON sub.subject_id=f.subject_id JOIN assessment_types at ON at.assessment_type_id=f.assessment_type_id JOIN paper_subject_mapping psm ON psm.batch_id=:b AND psm.paper_id=f.paper_id AND psm.subject_id=f.subject_id LEFT JOIN subject_faculty_mapping sfm ON sfm.batch_id=:b2 AND sfm.subject_id=f.subject_id AND sfm.faculty_id=f.faculty_id WHERE f.student_id=:s AND f.paper_id IS NOT NULL ORDER BY p.paper_name,sub.subject_name,at.assessment_type_id,f.entry_id");$q->execute([':b'=>$batchId,':b2'=>$batchId,':s'=>$studentId]);$rows=$q->fetchAll(PDO::FETCH_ASSOC);foreach($rows as $r)if((int)$r['entry_id']===$entryId)$edit=$r;}}
function fe($v):string{return htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');}$pageTitle='Full Marks Edit';require_once __DIR__.'/../../includes/header.php';
?><div style="display:flex;flex-direction:column;min-height:100vh"><?php require_once __DIR__.'/../../includes/navbar.php'; ?><div style="display:flex;flex:1"><?php require_once __DIR__.'/../../includes/sidebar.php'; ?><main style="flex:1;padding:30px;background:#f4f6f8"><h1 style="color:#1f4e79">Full Marks Edit</h1><?=displayFlash()?><div style="background:#fff;padding:20px;border-radius:8px;margin:20px 0"><form method="get"><label>Batch</label><select name="batch_id" onchange="this.form.submit()" style="width:100%;padding:10px"><option value="">Select Batch</option><?php foreach($batches as $b):?><option value="<?=$b['batch_id']?>" <?=$batchId==(int)$b['batch_id']?'selected':''?>><?=fe($b['batch_name'])?> (<?=fe($b['batch_number'])?>)</option><?php endforeach;?></select><?php if($batchId):?><label>Student</label><select name="student_id" onchange="this.form.submit()" style="width:100%;padding:10px"><option value="">Select Student</option><?php foreach($students as $st):?><option value="<?=$st['student_id']?>" <?=$studentId==(int)$st['student_id']?'selected':''?>><?=fe($st['roll_no'].' - '.$st['student_name'])?></option><?php endforeach;?></select><?php endif;?></form></div>
<?php if($student):?><div style="background:#fff;padding:20px;border-radius:8px;margin-bottom:20px"><h2>FULL MARKS EDIT</h2><p><b>Student Name:</b> <?=fe($student['student_name'])?> &nbsp; <b>Roll No:</b> <?=fe($student['roll_no'])?></p><p><b>Batch:</b> <?=fe(array_values(array_filter($batches,fn($b)=>(int)$b['batch_id']===$batchId))[0]['batch_name']??$batchId)?> &nbsp; <b>Designation:</b> <?=fe($student['designation'])?> &nbsp; <b>Qualification:</b> <?=fe($student['qualification'])?> &nbsp; <b>RMC:</b> <?=fe($student['rmc'])?></p></div><?php if($edit):?><div style="background:#fff;padding:20px;border-radius:8px;margin-bottom:20px"><h3>Edit Mark</h3><p><?=fe($edit['paper_name'])?> / <?=fe($edit['subject_name'])?> / <?=fe($edit['assessment_type_name'])?></p><form method="post" action="full_edit_save.php"><?=csrfField()?><input type="hidden" name="entry_id" value="<?=$entryId?>"><label>New Mark (Maximum <?=fe($edit['max_marks'])?>)</label><input type="number" name="new_marks" min="0" max="<?=fe($edit['max_marks'])?>" step="0.01" required style="width:100%;padding:10px"><label>Correction Reason</label><textarea name="reason" required minlength="3" style="width:100%;min-height:80px"></textarea><br><button type="submit">Save Changes</button></form></div><?php endif;?><div style="background:#fff;padding:20px;border-radius:8px"><table style="width:100%;border-collapse:collapse"><tr><th>Paper</th><th>Subject</th><th>Assessment</th><th>Current Mark</th><th>Maximum</th><th>Action</th></tr><?php foreach($rows as $r):?><tr><td><?=fe($r['paper_name'])?></td><td><?=fe($r['subject_name'])?></td><td><?=fe($r['assessment_type_name'])?></td><td><?=($r['is_absent']?'Absent':fe($r['marks_obtained']))?></td><td><?=fe($r['max_marks'])?></td><td><a href="?batch_id=<?=$batchId?>&student_id=<?=$studentId?>&entry_id=<?=$r['entry_id']?>">Edit</a></td></tr><?php endforeach;?></table></div><?php endif;?></main></div><?php require_once __DIR__.'/../../includes/footer.php';?></div>
